typedef float rational_t;

class vector3d
{
public:
	typedef rational_t T;
	T x,y,z;

	inline vector3d() {}
	inline vector3d(const vector3d& v) { x = v.x; y = v.y; z = v.z; }
	inline vector3d(T _x, T _y, T _z) { x = _x; y = _y; z = _z; }
	inline vector3d& operator = (const vector3d& v)
	{ x = v.x; y = v.y; z = v.z; return *this; }
};

inline vector3d operator + (const vector3d& a, const vector3d& b)
{ return vector3d(a.x + b.x, a.y + b.y, a.z + b.z); }

inline vector3d operator * (vector3d::T d, const vector3d& a)
{ return vector3d(d * a.x, d * a.y, d * a.z); }

typedef struct BeachDataStruct {
	char name[32];
	char folder[32];
	char stashfile[16];
	char fe_name[32];
	char career_name[32];
	char bottomname[32];
	char capsulename[32];
	int bdir;
	char rest[320];
} BeachData;

typedef struct WaveDataStruct {
	char name[32];
	float tileu;
	float tilev;
	float tileu_xbox;
	float tilev_xbox;
	float speedx;
	float speedz;
	char rest[528];
} WaveData;

class game
{
	char pad0[180];
	int num_ai_players;
	int num_active_players;
	char pad1[364];
	int beach_id;
public:
	int get_beach_id() { return beach_id; }
	bool is_splitscreen(void) { return num_active_players > 1 && num_ai_players == 0; }
	vector3d calc_beach_spawn_pos();
};

enum WaveMarkerEnum {
	WAVE_MarkerSplitscreenSpawnEnd = 51,
	WAVE_MarkerSpawnEnd = 52
};

extern game *g_game_ptr;
extern BeachData BeachDataArray[];
extern WaveData WaveDataArray[];
extern float g_takeoff_current_offset;
extern int WAVE_GetIndex(void);
extern const vector3d *WAVE_GetMarker(WaveMarkerEnum markernum);

__asm__(".equ g_game_ptr, 0x0045AC64");
__asm__(".equ BeachDataArray, 0x0042C198");
__asm__(".equ WaveDataArray, 0x004861E0");
__asm__(".equ g_takeoff_current_offset, 0x0041EC34");
__asm__(".equ WAVE_GetIndex__Fv, 0x0037D890");
__asm__(".equ WAVE_GetMarker__F14WaveMarkerEnum, 0x0037D7E8");

#define assert(x) ((void)0)

vector3d game::calc_beach_spawn_pos()
{
	int			curbeach = g_game_ptr->get_beach_id();
	int			current_wave = WAVE_GetIndex();
	vector3d	take_offset,spawnPos, current;

	if (BeachDataArray[curbeach].bdir)
		current.x = WaveDataArray[current_wave].speedx;
	else
		current.x = -WaveDataArray[current_wave].speedx;

	current.y = 0.0f;
	current.z = -WaveDataArray[current_wave].speedz;

	take_offset = - g_takeoff_current_offset*current;

	// Pick spawn position for player.
	if (!g_game_ptr->is_splitscreen())
	{
		spawnPos = *WAVE_GetMarker(WAVE_MarkerSpawnEnd) + take_offset;
	}
	// For splitscreen modes, we need to make sure player is starting in a safe spot.
	else
	{

		spawnPos = *WAVE_GetMarker(WAVE_MarkerSplitscreenSpawnEnd) + take_offset;
	}

	// make sure the surfer is inside the wave mesh
	assert ((spawnPos.x < WAVE_MeshMaxX) && (spawnPos.x > WAVE_MeshMinX) && (spawnPos.z < WAVE_MeshMaxZ) && (spawnPos.z > WAVE_MeshMinZ));

	return spawnPos;
}
